import {strict as assert} from 'node:assert';
import {readFileSync,writeFileSync,existsSync} from 'node:fs';
import {resolve} from 'node:path';
import {createCoverageMap} from 'istanbul-lib-coverage';
import {discoverInventory,validateInventory,sourceHash} from '../scripts/quality-inventory';
const base='.planning/memory-resilience/',read=(p:string)=>JSON.parse(readFileSync(p,'utf8'));
const path=base+'evidence/B11.74.3-friction.json',record=read(path),catalog=discoverInventory(process.cwd());
assert.equal(catalog.files.length,454);assert.equal(catalog.packages.length,2);assert.deepEqual(catalog,read(base+'executable-catalog.json'));assert.deepEqual(validateInventory(catalog,read(base+'quality-classifications.json')),[]);
for(const input of [...record.sourceInputs,...record.otherInputs])assert.equal(input.sourceHash,sourceHash(readFileSync(input.path,'utf8')));
for(const input of record.sourceInputs)for(const rows of [record.diagnosticCoverage.sourceInputs,record.decisionChecks.sourceInputs,record.native.sourceInputs])assert.equal(rows.find((r:any)=>r.path===input.path).sourceHash,input.sourceHash);
const coverage=createCoverageMap(record.diagnosticCoverage.measurement.rawCoverage);
for(const entry of record.diagnosticCoverage.measurement.files){assert.deepEqual(coverage.fileCoverageFor(resolve(entry.path)).toSummary().data,entry.metrics);for(const metric of Object.values(entry.metrics)as any[])assert.equal(metric.pct,100);}
for(const run of [record.checks[0],...record.native.runs]){assert.equal(run.exit,0);assert(run.output.includes('34 pass')&&run.output.includes('0 fail')&&run.output.includes('520 expect()'));}
assert.equal(record.decisionChecks.runs.length,22);assert.equal(record.decisionChecks.runs[0].exit,0);for(const run of record.decisionChecks.runs.slice(1)){assert.equal(run.exit,1);assert(run.output.includes('(fail)'));}
assert(!existsSync(record.removedRuntimeRoot));
const ledger=read(base+'work-items.json'),items=new Map<string,any>(ledger.items.map((i:any)=>[i.id,i])),done=new Set<string>();
function visit(id:string,stack=new Set<string>()){assert(items.has(id)&&!stack.has(id),'Invalid dependency '+id);if(done.has(id))return;for(const dep of items.get(id).depends_on)visit(dep,new Set([...stack,id]));done.add(id);}
assert.equal(items.size,232);assert.equal(items.size,ledger.items.length);for(const id of items.keys())visit(id);
assert.equal(ledger.current_item,'B11.74.3');assert.deepEqual(ledger.items.filter((i:any)=>i.status==='active').map((i:any)=>i.id),['B11.74.3']);
const inventory=items.get('B11.74.3').progress.repositoryInventory;assert.equal(inventory.length,17);assert.equal(inventory.filter((r:any)=>r.status.startsWith('local')).length,9);assert.equal(inventory.filter((r:any)=>r.status.startsWith('local')).reduce((n:number,r:any)=>n+r.nativePrepareSites,0),76);
for(const entry of inventory)assert.equal(entry.sourceHash,sourceHash(readFileSync(entry.path,'utf8')));
const frictionSource=readFileSync(record.sourceInputs[0].path,'utf8');assert.equal([...frictionSource.matchAll(/this\.db\.prepare[<(]/g)].length,19);assert(!frictionSource.includes('this.db.query('));assert(inventory.find((r:any)=>r.path===record.sourceInputs[0].path).queryDisposition);
assert.equal(items.get('B11.74').status,'pending');assert.equal(items.get('B11.74.6').status,'pending');assert(!readFileSync('src/infrastructure/database/connection.ts','utf8').includes('OwnedDatabase'));
record.validation={command:'bun .git/b11-friction-validate.ts',exit:0,recordedAt:new Date().toISOString(),result:'454-file/two-package inventory and 232-item acyclic ledger reconcile. Nine repositories/76 prepares locally migrated; friction cached query eliminated. Final source/native/metric/fault evidence agrees; full acceptance and factory activation pending.',source:readFileSync('.git/b11-friction-validate.ts','utf8')};
writeFileSync(path,JSON.stringify(record,null,2)+'\n');console.log(record.validation.result);
